			toolResult = unipoint.inspection_record.check_tool_availability(self.session, attrRecordId, '(Not Completed)')
			if toolResult.get('safeToProceed'):
				items[7] = {'state': 'completed', 'step': 'Checking Available Equipment', 'action': ''}
			else:
				blockedCount = toolResult.get('blockedAttributeCount', 0)
				items[7] = {'state': 'error', 'step': '{} tool group(s) short - review in Tool Selection'.format(blockedCount), 'action': ''}
		except Exception as e:
			items[7] = {'state': 'error', 'step': 'Equipment check error: {}'.format(str(e))}
		self.view.custom.prereqItems = list(items)

	# --- Build tool group summary for embedded view ---
	demandByGroup = toolResult.get('demandByGroup') or {}
	clearSupplyByGroup = toolResult.get('clearSupplyByGroup') or {}
	allGroups = sorted(set(list(demandByGroup.keys()) + list(clearSupplyByGroup.keys())))
	summary = []
	for group in allGroups:
